//! The coverage map (pr/78): for every recording x target round trip, how the lost and gained
//! key paths are explained (see `toolpath_goldens::classify`) and how many nothing explains. Read
//! from the committed `round_trip@<set>@<target>.snap` files. Two generated files are committed
//! and this test fails when either is stale:
//! * `docs/baseline/classification.md`, the counts per pair;
//! * `docs/baseline/unexplained.md`, the unexplained paths themselves (the defect candidates).
//!
//! Regenerate with `UPDATE_CLASSIFICATION=1 cargo test -p toolpath-goldens --test classification`.
//! Report mode: unexplained paths are counted, they do not fail the test (a later step does).

use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;

use serde::de::DeserializeOwned;
use serde_json::Value;
use toolpath_goldens::classify::{
    Classified, Declared, SourceBookkeeping, TargetSynthesized, Unexplained, classify_paths,
};
use toolpath_goldens::transform::Contract;

fn crate_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn load<T: DeserializeOwned>(rel: &str) -> T {
    let p = crate_dir().join(rel);
    let text = std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
    serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
}

fn set(v: &Value) -> BTreeSet<String> {
    v.as_array()
        .into_iter()
        .flatten()
        .map(|p| p.as_str().expect("a key path").to_owned())
        .collect()
}

type Rows = BTreeMap<(String, String), (Classified, Unexplained)>;

/// `(recording set, target) -> classified`, plus the pairs whose round trip was unreadable.
fn measure() -> (Rows, Vec<String>) {
    let book: Vec<SourceBookkeeping> = load("fixtures/source-bookkeeping.json");
    let synth: Vec<TargetSynthesized> = load("fixtures/target-synthesized.json");
    assert!(
        book.iter().all(|d| d.why.len() >= 20) && synth.iter().all(|d| d.why.len() >= 20),
        "every declaration gives a reason"
    );
    let mut out = BTreeMap::new();
    let mut unreadable = Vec::new();
    let mut contracts: BTreeMap<String, Contract> = BTreeMap::new();
    for entry in std::fs::read_dir(crate_dir().join("snapshots")).expect("snapshots") {
        let name = entry
            .expect("entry")
            .file_name()
            .to_string_lossy()
            .into_owned();
        let Some(rest) = name
            .strip_prefix("round_trip@")
            .and_then(|r| r.strip_suffix(".snap"))
        else {
            continue;
        };
        let (set_name, target) = rest.split_once('@').expect("round_trip@<set>@<target>");
        let text = std::fs::read_to_string(crate_dir().join("snapshots").join(&name)).unwrap();
        let body = text.splitn(3, "---\n").nth(2).expect("snapshot body");
        let v: Value = serde_json::from_str(body).unwrap_or_else(|e| panic!("{name}: {e}"));
        if v["outcome"] != "compared" {
            unreadable.push(format!("{set_name} -> {target}"));
            continue;
        }
        let contract = contracts
            .entry(target.to_owned())
            .or_insert_with(|| load(&format!("fixtures/contract/{target}.json")));
        // claude-session and claude-compacted are recordings of the claude agent
        // (and `<agent>-forced` is a compaction forced in that agent)
        let source = set_name.split('-').next().unwrap_or(set_name);
        let d = Declared {
            contract,
            source,
            source_bookkeeping: &book,
            target_synthesized: &synth,
        };
        out.insert(
            (set_name.to_owned(), target.to_owned()),
            classify_paths(&d, &set(&v["lost"]), &set(&v["gained"])),
        );
    }
    (out, unreadable)
}

fn render(rows: &Rows, unreadable: &[String]) -> String {
    let mut s = String::from(
        "# Classification of lost and gained key paths on the real round trips\n\n\
         Generated by `tests/classification.rs` from the committed `round_trip@*` snapshots, \
         `fixtures/contract/<target>.json`, `fixtures/source-bookkeeping.json` and \
         `fixtures/target-synthesized.json`. Regenerate with `UPDATE_CLASSIFICATION=1 cargo test -p \
         toolpath-goldens --test classification`. The unexplained paths themselves are in \
         `unexplained.md`.\n\n\
         **Report mode (pr/78).** A *lost* path is *dropped* (the target's contract has a drop op \
         for it), *renamed* (a rename/move op names it), *source* (it lies under the recording \
         agent's own envelope), else *unexplained*. A *gained* path is *synthesized* (a synthesize \
         op, or the envelope the target writer mints for every session), *renamed* (the other \
         side of a rename/move op), else *unexplained*. Unexplained does not fail anything until \
         Bobby says so.\n\n\
         | recording | target | lost dropped | lost renamed | lost source | lost unexplained | gained synthesized | gained renamed | gained unexplained |\n\
         |---|---|---:|---:|---:|---:|---:|---:|---:|\n",
    );
    let mut t = Classified::default();
    for ((set, target), (c, _)) in rows {
        s.push_str(&format!(
            "| {set} | {target} | {} | {} | {} | {} | {} | {} | {} |\n",
            c.lost_dropped,
            c.lost_renamed,
            c.lost_source,
            c.lost_unexplained,
            c.gained_synthesized,
            c.gained_renamed,
            c.gained_unexplained
        ));
        t.lost_dropped += c.lost_dropped;
        t.lost_renamed += c.lost_renamed;
        t.lost_source += c.lost_source;
        t.lost_unexplained += c.lost_unexplained;
        t.gained_synthesized += c.gained_synthesized;
        t.gained_renamed += c.gained_renamed;
        t.gained_unexplained += c.gained_unexplained;
    }
    s.push_str(&format!(
        "| **{} pairs** | | **{}** | **{}** | **{}** | **{}** | **{}** | **{}** | **{}** |\n",
        rows.len(),
        t.lost_dropped,
        t.lost_renamed,
        t.lost_source,
        t.lost_unexplained,
        t.gained_synthesized,
        t.gained_renamed,
        t.gained_unexplained
    ));
    if !unreadable.is_empty() {
        s.push_str(&format!(
            "\nRound trips the adapter could not read (not classified): {}\n",
            unreadable.join(", ")
        ));
    }
    s
}

fn render_unexplained(rows: &Rows) -> String {
    let mut s = String::from(
        "# Unexplained key paths (the defect candidates)\n\n\
         Generated with `classification.md`. For each recording and target, the lost and gained \
         paths no declaration explains. A value the target format can hold is a reader or writer \
         bug; a value it cannot hold gets a declaration with a reason.\n",
    );
    for ((set, target), (_, u)) in rows {
        if u.lost.is_empty() && u.gained.is_empty() {
            continue;
        }
        s.push_str(&format!("\n## {set} -> {target}\n"));
        for p in &u.lost {
            s.push_str(&format!("- lost `{p}`\n"));
        }
        for p in &u.gained {
            s.push_str(&format!("- gained `{p}`\n"));
        }
    }
    s
}

#[test]
fn the_committed_classification_tables_are_current() {
    let (rows, unreadable) = measure();
    let files = [
        ("classification.md", render(&rows, &unreadable)),
        ("unexplained.md", render_unexplained(&rows)),
    ];
    for (name, now) in files {
        let path = crate_dir().join("../../docs/baseline").join(name);
        if std::env::var_os("UPDATE_CLASSIFICATION").is_some() {
            std::fs::write(&path, &now).expect("write the table");
            continue;
        }
        let committed = std::fs::read_to_string(&path).unwrap_or_default();
        assert_eq!(
            committed, now,
            "docs/baseline/{name} is stale; regenerate it with UPDATE_CLASSIFICATION=1"
        );
    }
}

#[test]
fn every_recording_and_target_is_classified() {
    let (rows, unreadable) = measure();
    // 9 recordings x 7 targets, and the 4 compactions forced in the agents x 7 targets
    assert_eq!(rows.len() + unreadable.len(), 91, "one row per round trip");
}
